<?php
require __DIR__ . '/../config.php'; admin_required(); $pdo=db(); $page=$_GET['page']??'dashboard';
function nav(string $key,string $label,string $page):string{return '<a class="'.($key===$page?'active':'').'" href="?page='.$key.'">'.$label.'</a>';}
if(isset($_GET['logout'])){session_destroy();header('Location: login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
  if(($_POST['action']??'')==='password'){ if(strlen($_POST['password']??'')>=10) $pdo->prepare('UPDATE admins SET password_hash=? WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$_SESSION['admin']]); $page='password'; }
  if(($_POST['action']??'')==='delete'){ $table=$_POST['table']; if(in_array($table,['products','reviews','promotions','brands','categories'],true)) $pdo->prepare("DELETE FROM `$table` WHERE id=?")->execute([(int)$_POST['id']]); }
  if(($_POST['action']??'')==='product'){
    $f=$_POST; $slug=trim($f['slug']) ?: strtolower(trim(preg_replace('/[^a-z0-9]+/i','-', $f['name']),'-')); $f['slug']=$slug;
    try { if ($uploaded = upload_product_image($_FILES['image_file'] ?? [])) $f['image_url'] = $uploaded; } catch (RuntimeException $e) { header('Location: ?page=products&edit='.urlencode($f['id'] ?? 'new').'&error='.urlencode($e->getMessage())); exit; }
    $cols=['name','slug','sku','brand_id','category_id','short_description','description','price','old_price','monthly_payment','in_stock','is_new','is_hit','is_sale','is_active','image_url','processor','gpu','ram','storage','display_size','resolution','refresh_rate','matrix_type','warranty']; $values=[]; foreach($cols as $c)$values[]=(($c==='in_stock'||str_starts_with($c,'is_'))?isset($f[$c]):($f[$c]??null));
    if(!empty($f['id'])){$set=implode(',',array_map(fn($c)=>"$c=?",$cols));$values[]=(int)$f['id'];$pdo->prepare("UPDATE products SET $set WHERE id=?")->execute($values);}else{$pdo->prepare('INSERT INTO products('.implode(',',$cols).') VALUES('.rtrim(str_repeat('?,',count($cols)),',').')')->execute($values);} $page='products';
  }
  if(($_POST['action']??'')==='review'){ $pdo->prepare('INSERT INTO reviews(product_id,author_name,initials,rating,body,source,is_approved) VALUES(?,?,?,?,?,?,?)')->execute([$_POST['product_id']?:null,$_POST['author_name'],$_POST['initials'],$_POST['rating'],$_POST['body'],$_POST['source'],isset($_POST['is_approved'])]);$page='reviews';}
  if(($_POST['action']??'')==='promotion'){ $cols=['title','description','badge','button_text','button_url','color','sort_order','is_active'];$v=[];foreach($cols as $c)$v[]=$c==='is_active'?isset($_POST[$c]):$_POST[$c];if(!empty($_POST['id'])){$v[]=$_POST['id'];$pdo->prepare('UPDATE promotions SET '.implode(',',array_map(fn($c)=>"$c=?",$cols)).' WHERE id=?')->execute($v);}else $pdo->prepare('INSERT INTO promotions('.implode(',',$cols).') VALUES('.rtrim(str_repeat('?,',count($cols)),',').')')->execute($v);$page='promotions';}
  header('Location: ?page='.$page.'&saved=1');exit;
}
$counts=['products'=>$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),'reviews'=>$pdo->query('SELECT COUNT(*) FROM reviews')->fetchColumn(),'leads'=>$pdo->query('SELECT COUNT(*) FROM leads')->fetchColumn(),'promotions'=>$pdo->query('SELECT COUNT(*) FROM promotions')->fetchColumn()];
?><!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OnePoint Admin</title><style>:root{--a:#ff5a1f;--d:#15161d;--l:#f5f6f8}*{box-sizing:border-box}body{font:15px system-ui;margin:0;background:var(--l);color:#191a20}.side{position:fixed;width:230px;inset:0 auto 0 0;background:var(--d);color:#fff;padding:25px 14px}.side h2{padding:0 12px;margin:0 0 28px}.side a{display:block;color:#c6c7ce;padding:12px;border-radius:9px;text-decoration:none}.side a.active,.side a:hover{background:#282a34;color:#fff}.main{margin-left:230px;padding:34px;max-width:1500px}.top{display:flex;justify-content:space-between;align-items:center}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card,form.box{background:#fff;border-radius:14px;padding:20px;border-radius:14px;box-shadow:0 2px 10px #0000000a}.num{font-size:30px;font-weight:800}.toolbar{display:flex;gap:12px;justify-content:space-between;margin:25px 0}.btn,button{background:var(--a);color:#fff;border:0;border-radius:8px;padding:10px 14px;text-decoration:none;font-weight:700;cursor:pointer}.ghost{background:#fff;color:#222;border:1px solid #ddd}table{width:100%;border-collapse:collapse;background:#fff;border-radius:12px;overflow:hidden}th,td{padding:12px;text-align:left;border-bottom:1px solid #eee;vertical-align:top}th{font-size:12px;color:#6d6e76;text-transform:uppercase}input,textarea,select{width:100%;padding:10px;border:1px solid #d9dae0;border-radius:7px;margin:5px 0 13px;font:inherit}textarea{min-height:90px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.checks{display:flex;gap:14px;flex-wrap:wrap}.checks label{display:flex;gap:5px;align-items:center}.checks input{width:auto;margin:0}.notice{background:#e8f7ef;padding:10px;border-radius:8px;color:#167242}@media(max-width:760px){.side{position:static;width:auto}.main{margin:0;padding:18px}.cards,.grid{grid-template-columns:1fr}.side a{display:inline-block}.side h2{margin-bottom:10px}table{font-size:12px}.hide-sm{display:none}}</style><body><aside class="side"><h2>● OnePoint</h2><?=nav('dashboard','Обзор',$page)?><?=nav('products','Ноутбуки',$page)?><?=nav('reviews','Отзывы',$page)?><?=nav('promotions','Акции',$page)?><?=nav('leads','Заявки',$page)?><?=nav('password','Пароль',$page)?><a href="?logout=1">Выйти</a></aside><main class="main"><div class="top"><h1><?=['dashboard'=>'Обзор','products'=>'Ноутбуки','reviews'=>'Отзывы','promotions'=>'Акции','leads'=>'Заявки','password'=>'Пароль'][$page]??'Админка'?></h1><a href="../install.php" class="ghost">Импорт текущих данных</a></div><?php if(isset($_GET['saved'])):?><p class="notice">Сохранено</p><?php endif;?>
<?php if($page==='dashboard'):?><div class="cards"><?php foreach(['products'=>'Ноутбуков','reviews'=>'Отзывов','promotions'=>'Акций','leads'=>'Заявок'] as $k=>$t):?><div class="card"><div class="num"><?=$counts[$k]?></div><div><?=$t?></div></div><?php endforeach?></div><div class="card" style="margin-top:20px"><b>Быстрый старт</b><p>Товары, характеристики, цены, остатки, флаги «Хит/Акция/Новинка», отзывы и баннеры редактируются отсюда. Для сайта доступен API: <code>/backend/api/products.php</code>.</p></div>
<?php elseif($page==='products'): $edit=isset($_GET['edit'])?$pdo->prepare('SELECT * FROM products WHERE id=?'):null;if($edit){$edit->execute([$_GET['edit']]);$p=$edit->fetch();}else $p=[];$brands=$pdo->query('SELECT * FROM brands ORDER BY name')->fetchAll();$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();?>
<div class="toolbar"><a class="btn" href="?page=products&edit=new">+ Добавить ноутбук</a><span>Всего: <?=$counts['products']?></span></div><?php if(isset($_GET['edit'])):?><form class="box" method="post"><input type="hidden" name="action" value="product"><input type="hidden" name="id" value="<?=e($p['id']??'')?>"><div class="grid"><label>Название<input name="name" required value="<?=e($p['name']??'')?>"></label><label>URL-slug<input name="slug" value="<?=e($p['slug']??'')?>"></label><label>Артикул<input name="sku" value="<?=e($p['sku']??'')?>"></label><label>Бренд<select name="brand_id"><?php foreach($brands as $b):?><option value="<?=$b['id']?>" <?=($p['brand_id']??'')==$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach?></select></label><label>Категория<select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($p['category_id']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></label><label>Изображение (URL)<input name="image_url" value="<?=e($p['image_url']??'')?>"></label><label>Цена, ₸<input name="price" type="number" required value="<?=e($p['price']??'')?>"></label><label>Старая цена<input name="old_price" type="number" value="<?=e($p['old_price']??'')?>"></label><label>Цена/мес.<input name="monthly_payment" type="number" value="<?=e($p['monthly_payment']??'')?>"></label><label>Процессор<input name="processor" value="<?=e($p['processor']??'')?>"></label><label>Видеокарта<input name="gpu" value="<?=e($p['gpu']??'')?>"></label><label>ОЗУ<input name="ram" value="<?=e($p['ram']??'')?>"></label><label>SSD<input name="storage" value="<?=e($p['storage']??'')?>"></label><label>Экран<input name="display_size" value="<?=e($p['display_size']??'')?>"></label><label>Частота<input name="refresh_rate" value="<?=e($p['refresh_rate']??'')?>"></label></div><label>Краткое описание<textarea name="short_description"><?=e($p['short_description']??'')?></textarea></label><label>Полное описание<textarea name="description"><?=e($p['description']??'')?></textarea></label><div class="checks"><?php foreach(['in_stock'=>'В наличии','is_hit'=>'Хит','is_sale'=>'Акция','is_new'=>'Новинка','is_active'=>'Показывать'] as $k=>$t):?><label><input type="checkbox" name="<?=$k?>" <?=($p[$k]??1)?'checked':''?>><?=$t?></label><?php endforeach?></div><p><button>Сохранить</button> <a href="?page=products">Отмена</a></p></form><?php endif;?><?php $rows=$pdo->query('SELECT p.*,b.name brand FROM products p LEFT JOIN brands b ON b.id=p.brand_id ORDER BY p.id DESC')->fetchAll();?><table><tr><th>Ноутбук</th><th>Цена</th><th class="hide-sm">Статус</th><th></th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><br><small><?=e($r['brand']??'')?></small></td><td><?=number_format((float)$r['price'],0,'.',' ')?> ₸</td><td class="hide-sm"><?=($r['is_active']?'Активен':'Скрыт')?> <?=($r['is_hit']?'· Хит':'')?> <?=($r['is_sale']?'· Акция':'')?></td><td><a class="btn" href="?page=products&edit=<?=$r['id']?>">Изменить</a></td></tr><?php endforeach?></table>
<?php elseif($page==='reviews'):?><div class="toolbar"><a class="btn" href="?page=reviews&add=1">+ Добавить отзыв</a></div><?php if(isset($_GET['add'])):?><form class="box" method="post"><input type="hidden" name="action" value="review"><div class="grid"><label>Автор<input name="author_name" required></label><label>Инициалы<input name="initials"></label><label>Оценка<select name="rating"><?php for($i=5;$i>=1;$i--):?><option><?=$i?></option><?php endfor?></select></label></div><label>Текст<textarea name="body" required></textarea></label><label>Источник<input name="source" value="site"></label><label class="checks"><input type="checkbox" name="is_approved" checked>Показывать</label><p><button>Сохранить</button></p></form><?php endif;$rows=$pdo->query('SELECT * FROM reviews ORDER BY id DESC')->fetchAll();?><table><tr><th>Автор</th><th>Отзыв</th><th>Оценка</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['author_name'])?></td><td><?=e($r['body'])?></td><td>★ <?=$r['rating']?></td><td><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="reviews"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="ghost">Удалить</button></form></td></tr><?php endforeach?></table>
<?php elseif($page==='promotions'): $edit=isset($_GET['edit'])?$pdo->prepare('SELECT * FROM promotions WHERE id=?'):null;if($edit){$edit->execute([$_GET['edit']]);$x=$edit->fetch();}else $x=[];?><div class="toolbar"><a class="btn" href="?page=promotions&edit=new">+ Добавить акцию</a></div><?php if(isset($_GET['edit'])):?><form class="box" method="post"><input type="hidden" name="action" value="promotion"><input type="hidden" name="id" value="<?=e($x['id']??'')?>"><div class="grid"><label>Заголовок<input name="title" required value="<?=e($x['title']??'')?>"></label><label>Бейдж<input name="badge" value="<?=e($x['badge']??'')?>"></label><label>Цвет<select name="color"><option>orange</option><option>dark</option><option>blue</option></select></label><label>Текст кнопки<input name="button_text" value="<?=e($x['button_text']??'')?>"></label><label>Ссылка<input name="button_url" value="<?=e($x['button_url']??'')?>"></label><label>Порядок<input name="sort_order" type="number" value="<?=e($x['sort_order']??0)?>"></label></div><label>Описание<textarea name="description"><?=e($x['description']??'')?></textarea></label><label class="checks"><input type="checkbox" name="is_active" checked>Показывать</label><p><button>Сохранить</button></p></form><?php endif;$rows=$pdo->query('SELECT * FROM promotions ORDER BY sort_order,id')->fetchAll();?><table><tr><th>Акция</th><th>Описание</th><th></th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['title'])?></b><br><small><?=e($r['badge'])?></small></td><td><?=e($r['description'])?></td><td><a class="btn" href="?page=promotions&edit=<?=$r['id']?>">Изменить</a></td></tr><?php endforeach?></table>
<?php elseif($page==='leads'): $rows=$pdo->query('SELECT * FROM leads ORDER BY id DESC')->fetchAll();?><table><tr><th>Дата</th><th>Клиент</th><th>Контакты</th><th>Сообщение</th><th>Статус</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name'])?></td><td><?=e($r['phone'])?><br><?=e($r['email'])?></td><td><?=e($r['message'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach?></table>
<?php elseif($page==='password'):?><form class="box" method="post" style="max-width:480px"><input type="hidden" name="action" value="password"><label>Новый пароль (минимум 10 символов)<input name="password" type="password" minlength="10" required></label><button>Сменить пароль</button></form><?php endif;?></main></body></html>
